<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<style>
  body {
    margin: 0;
    padding: 0;
    width: 1920px;
    height: 1080px;
    overflow: hidden;
    background-color: #ffffff;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  .shell {
    position: absolute;
    top: 0;
    left: 0;
    width: 1920px;
    height: 1080px;
    z-index: -1;
  }
  .content {
    position: absolute;
    top: 160px;
    left: 160px;
    width: 1600px;
    z-index: 1;
  }
  h1 {
    font-size: 64px;
    font-weight: 800;
    color: #001533;
    margin: 0;
    letter-spacing: -1px;
  }
  p.subtitle {
    font-size: 36px;
    font-weight: 400;
    color: #4a5568;
    margin: 16px 0 0 0;
  }
  .cards-container {
    display: flex;
    justify-content: space-between;
    gap: 24px;
    margin-top: 100px;
    height: 420px;
    position: relative;
  }
  /* Subtle connecting line behind cards */
  .cards-container::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 0;
    width: 100%;
    height: 2px;
    background: #e2e8f0;
    z-index: -1;
    transform: translateY(-50%);
  }
  .card {
    flex: 1;
    background: #ffffff;
    border: 1px solid #f1f5f9;
    border-top: 8px solid #00205b;
    border-radius: 12px;
    padding: 40px 32px;
    display: flex;
    flex-direction: column;
    box-shadow: 0 12px 30px rgba(0, 21, 51, 0.06);
    position: relative;
  }
  .card:nth-child(1) { border-top-color: #00205b; }
  .card:nth-child(2) { border-top-color: #0055a4; }
  .card:nth-child(3) { border-top-color: #4b9cd3; }
  .card:nth-child(4) { border-top-color: #e31837; }
  .card:nth-child(5) { border-top-color: #8a1538; }

  .card-num {
    font-size: 72px;
    font-weight: 900;
    color: #f1f5f9;
    line-height: 0.8;
    position: absolute;
    top: 32px;
    right: 32px;
    letter-spacing: -2px;
  }
  .card-icon {
    width: 48px;
    height: 48px;
    margin-bottom: 40px;
  }
  .card:nth-child(1) .card-icon { color: #00205b; }
  .card:nth-child(2) .card-icon { color: #0055a4; }
  .card:nth-child(3) .card-icon { color: #4b9cd3; }
  .card:nth-child(4) .card-icon { color: #e31837; }
  .card:nth-child(5) .card-icon { color: #8a1538; }

  .card-title {
    font-size: 34px;
    font-weight: 700;
    color: #001533;
    line-height: 1.15;
    margin-top: 10px;
    text-transform: capitalize;
  }
  .card-cite {
    margin-top: auto;
    font-size: 18px;
    font-weight: 600;
    color: #94a3b8;
    background: #f8fafc;
    padding: 6px 12px;
    border-radius: 6px;
    align-self: flex-start;
  }
</style>
</head>
<body>
  <img class="shell" src="../../../../templates/saem-annual-meeting-template-v1/template.png" alt="" aria-hidden="true" />

  <div class="content">
