    <p class="subtitle">Keep it brief, specific, active, and mobile-first.</p>

    <div class="cards-container">
      <div class="card">
        <div class="card-num">01</div>
        <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="12" cy="12" r="10"></circle>
          <circle cx="12" cy="12" r="4"></circle>
        </svg>
        <div class="card-title">One<br>objective</div>
        <div class="card-cite">[1]</div>
      </div>

      <div class="card">
        <div class="card-num">02</div>
        <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M22 12h-4l-3 9L9 3l-3 9H2"></path>
        </svg>
        <div class="card-title">Clinical<br>relevance</div>
        <div class="card-cite">[7]</div>
      </div>

      <div class="card">
        <div class="card-num">03</div>
        <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
          <path d="M9 12l2 2 4-4"></path>
        </svg>
        <div class="card-title">Active<br>response</div>
        <div class="card-cite">[13]</div>
      </div>

      <div class="card">
        <div class="card-num">04</div>
        <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <rect x="5" y="2" width="14" height="20" rx="2" ry="2"></rect>
          <path d="M12 18h.01"></path>
          <path d="M8 2h8"></path>
        </svg>
        <div class="card-title">Mobile<br>friction</div>
        <div class="card-cite">[20]</div>
      </div>

      <div class="card">
        <div class="card-num">05</div>
        <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path>
        </svg>
        <div class="card-title">Feedback</div>
        <div class="card-cite">[27]</div>
      </div>
    </div>
  </div>
</body>
</html>
